import {CROPS,ITEMS,BUILDINGS,REGIONS,WEAPONS} from './data.js';
import {FEATURES,KIT,MODULES,HERBS,CLUES,CANAL} from './frontier-data.js';
export const FRONTIER_TABS=[['overview','家园与远行'],['land','土地'],['rooms','房间与政策'],['water','水渠'],['ecology','生态'],['expedition','远征'],['combat','战术'],['investigation','调查'],['life','伙伴与摄影'],['kitchen','料理'],['exhibition','收获展']];
const names={butterfly:'蝴蝶',frog:'青蛙',egret:'白鹭',empty:'空地',grass:'草地',forest:'林地',wetland:'湿地',field:'耕地',noGuns:'禁枪',timed:'三分钟撤离',oneHeal:'限用一份药',explorer:'三站探索者',towerPond:'水塔与池塘同框',rainSign:'雨中的留言板',workingResident:'工作中的居民',frogPhoto:'修复区的青蛙'};
export function renderFrontier(engine,tab='overview',h,state={}){
 const {esc,itemIcon,costs,itemName}=h,s=engine.s,f=engine.f;
 const button=(action,label,id='',extra='',disabled=false)=>`<button data-action="${action}" data-id="${esc(id)}" ${extra} ${disabled?'disabled':''}>${label}</button>`;
 const fi=(n,label='')=>`<canvas class="frontier-icon" data-frontier="${n}" aria-label="${esc(label)}"></canvas>`;
 const card=(title,body,extra='')=>`<article class="frontier-card ${extra}"><h3>${title}</h3>${body}</article>`;
 const note=text=>`<p class="frontier-note">${text}</p>`;
 const farm=s.region==='farm',disabledFarm=!farm;
 const tabs=`<nav class="frontier-tabs" aria-label="成长与探索分类">${FRONTIER_TABS.map(([id,name])=>button('frontierTab',name,id,`class="${tab===id?'active':''}" aria-pressed="${tab===id}"`)).join('')}</nav>`;
 let body='';
 if(tab==='overview'){
  body=note('安排家园与远行。查看土地、设备和补给，为下一次出发做好准备。')+`<div class="frontier-grid">${FEATURES.map(d=>card(d.name,`<p>${d.desc}</p><div class="card-foot">${button('frontierTab','查看与安排',d.tab)}</div>`)).join('')}</div>`;
 }else if(tab==='land'){
  const p=s.plots.find(p=>p.id===state.plotId)||s.plots.find(p=>Math.hypot(p.x-s.player.x,p.y-s.player.y)<110)||s.plots[0],crop=state.previewCrop||'bean',forecast=engine.soilForecast(p,crop),a=engine.adjacent(p,p.crop||crop);
  body=note('肥力低于30，生长速度降至65%；85以上提高12%。空地每天恢复2。豆类收获后补充22肥力，连种同一作物额外消耗8。')+`<div class="frontier-grid">${card('农田肥力',`<div class="soil-grid">${s.plots.slice(0,80).map(q=>button('fPlot',`${q.crop?CROPS[q.crop].name:'空地'}<small>${Math.round(q.fertility)}</small>`,q.id,`class="soil-cell ${q.id===p.id?'selected':''}" style="--fert:${q.fertility/100}" aria-label="地块${q.id+1}，肥力${Math.round(q.fertility)}"`)).join('')}</div>${button('fSoilView',f.soilView?'关闭地面肥力标记':'显示地面肥力标记')}`)}${card('地块 '+(p.id+1)+' · 播种预测',`<p>肥力 <b>${Math.round(p.fertility)}</b> · 上次收成 ${p.lastCrop?CROPS[p.lastCrop].name:'无'}<br>当前 ${p.crop?CROPS[p.crop].name:'未种植'} · ${p.crop?'成长 '+Math.round(p.growth/CROPS[p.crop].grow*100)+'%':''}</p><label>计划种植<select id="f-preview-crop">${Object.entries(CROPS).map(([id,c])=>`<option value="${id}" ${crop===id?'selected':''}>${c.name}</option>`).join('')}</select></label><p>播种后肥力 <strong>${Math.round(forecast.after)}</strong> · ${forecast.repeat?'连种额外消耗8':forecast.rotation?'换作物，避免连种消耗':'常规种植'}<br>邻接预计：产量 +${a.yield} / 品质机会 +${a.quality}</p>${button('equipSeed','装备'+CROPS[crop].name+'种子',CROPS[crop].seed,'class="primary"',!engine.qty(CROPS[crop].seed))}<p class="muted">返回田地，靠近空地按 E 播种。玉米与豆类、番茄与草药相邻时会显示加成。</p>`)}</div>`;
 }else if(tab==='rooms'){
  body=(disabledFarm?note('返回农场后可以摆放家具和调整政策。'):'')+`<div class="frontier-grid">${card('家具组合',`<p>地板周围75步内放置 <b>木椅＋暖光灯</b> 形成休息室。再加餐桌成为食堂，或加书架成为阅览室。</p><div class="furniture-list">${['floor','chair','lamp','table','bookshelf','harvestTrophy'].map(id=>`<div>${BUILDINGS[id].frontierIcon!=null?fi(BUILDINGS[id].frontierIcon):itemIcon('wood')}<span>${BUILDINGS[id].name}${costs(BUILDINGS[id].cost)}</span>${button('build','建造',id,'',disabledFarm||id==='harvestTrophy'&&!f.trophies)}</div>`).join('')}</div>`)}${card('功能房间与居民',`${engine.rooms().length?engine.rooms().map(r=>`<p><b>${r.type}</b> · 农舍周边<br>${r.active?'房间已启用 · 在附近每小时恢复8耐力':'还需要木椅与暖光灯'}</p>`).join(''):'<p>尚未铺设房间地板。</p>'}<p>阿禾喜欢休息室，医生喜欢食堂，陈工喜欢阅览室。闲时会前往房间，疲劳每小时降低8。</p>${engine.c.residents.map(r=>`<div class="resident-line"><b>${esc(r.id==='medic'?'许医生':r.id==='farmer'?'阿禾':'陈工')}</b><span>疲劳 ${Math.round(r.fatigue)} · 心情 ${Math.round(r.morale)}</span><small>${esc(r.status||'等待工作')}</small></div>`).join('')}`)}${card('工作政策',`<p>标准工作每小时增加2疲劳；加班增加7，并让农夫多收一株、维修工多修一处、医生额外治疗。疲劳达到85暂停工作，过夜恢复18。</p><div class="button-row">${['standard','overtime'].map(value=>button('fPolicy',value==='standard'?'标准工作':'加班生产',value,`data-kind="work" class="${f.policy.work===value?'primary':''}"`,disabledFarm)).join('')}</div>`)}${card('食物政策',`<p>工作餐仍需面包和床位。平均分配增加全员心情；伤员优先先供给医生，生命低于70时额外治疗6，其他居民会表达不满。</p><div class="button-row">${['equal','injured'].map(value=>button('fPolicy',value==='equal'?'平均分配':'伤员优先',value,`data-kind="food" class="${f.policy.food===value?'primary':''}"`,disabledFarm)).join('')}${button('feedResidents','提供工作餐','','',disabledFarm)}</div>`)}</div>`;
 }else if(tab==='water'){
  const flow=engine.canalFlow();
  body=note('从左上角水源连通至右下角蓄水口。蓝色为有水格，5号格是闸门；水位达到2会淹没池塘北侧浅滩。')+`<div class="frontier-grid">${card('水渠布局 · 每格1石头',`<div class="canal-grid">${Array.from({length:16},(_,i)=>button('fDigCanal',`${i===0?'水源':i===15?'蓄水':i===CANAL.gate?'闸门':i+1}<small>${flow.includes(i)?'有水':f.canals.dug.includes(i)?'已挖':'挖渠'}</small>`,i,`class="${flow.includes(i)?'flowing':f.canals.dug.includes(i)?'dug':''}"`,disabledFarm||f.canals.dug.includes(i))).join('')}</div>`)}${card('闸门与水位',`${fi(15,'水闸')}<p>水位 <strong>${f.canals.level} / 3</strong> · ${f.canals.level>=2?'浅滩被水淹没':'浅滩可以通行'}<br>水渠 ${flow.includes(15)?'已连通':'尚未连通'} · 闸门${f.canals.open?'开启':'关闭'}<br>农场储水 ${engine.c.water} / ${engine.c.waterCapacity}</p><div class="button-row">${button('fWaterControl',f.canals.open?'关闭闸门':'开启闸门','gate','',disabledFarm)}${button('fWaterControl','蓄水灌溉','hold',`class="${f.canals.mode==='hold'?'primary':''}"`,disabledFarm)}${button('fWaterControl','排水开放浅滩','drain',`class="${f.canals.mode==='drain'?'primary':''}"`,disabledFarm)}</div><p>连通后每游戏小时消耗1水，给水渠周围190步内作物浇水。排水立即开放浅滩。</p>`)}</div>`;
 }else if(tab==='ecology'){
  const op=state.ecoTool||'clean';
  body=note('东北角是一片污染地。清理后可以恢复自然，也可开垦；改造耕地前需要先收获作物。动物回归后会一直留在营地。')+`<div class="frontier-grid">${card('修复区',`<label>操作<select id="f-eco-tool">${[['clean','清理 · 草药1＋废铁1'],['grass','草地 · 豆类1'],['forest','林地 · 木材2'],['wetland','湿地 · 石头1'],['field','耕地 · 木材2']].map(([id,label])=>`<option value="${id}" ${id===op?'selected':''}>${label}</option>`).join('')}</select></label><div class="eco-grid">${f.ecology.map((t,i)=>button('fEcology',`${t.clean?names[t.type]:'污染'}<small>${i+1}</small>`,i,`class="eco-${t.clean?t.type:'polluted'}"`,disabledFarm)).join('')}</div><p>已清理 ${f.ecology.filter(t=>t.clean).length}/16 · 连通自然区 ${engine.ecologyConnected().length} 片</p>`)}${card('回归的生命',`<div class="species-list">${[['butterfly',1,'同一片自然区：2草地＋1林地'],['frog',2,'同一片自然区：3湿地＋1草地'],['egret',3,'同一片自然区：3林地＋2湿地，清理12格']].map(([id,index,rule])=>`<div class="${f.species.includes(id)?'returned':'waiting'}">${fi(index)}<span><b>${names[id]} · ${f.species.includes(id)?'已经回归':'等待环境恢复'}</b><small>${rule}</small></span></div>`).join('')}</div><p>每种动物首次回归奖励2草药种子，存入仓库。</p>`)}</div>`;
 }else if(tab==='expedition'){
  const kitId=state.kitId||'club',rotation=state.kitRotation||0,r=f.route,occ=engine.kitOccupancy()||new Map(),cargo=new Map((r?.cells||[]).map(c=>[c.cell,c.id]));
  body=note('远征物资必须在随身背包中。枪械、口粮、弹药与药品只可使用装入行囊的数量；每种战利品每10件占1空格。短途探索使用随身背包。')+`<div class="frontier-grid">${card('4×4远征行囊',`<div class="pack-grid">${Array.from({length:16},(_,i)=>{const id=occ.get(i),loot=cargo.get(i);return button('fPlaceKit',id?KIT[id].name:loot?itemName(loot):'放入',i,`class="${id?'packed':loot?'cargo':''}" aria-label="行${Math.floor(i/4)+1}列${i%4+1} ${id?KIT[id].name:loot?itemName(loot):'空格'}"`,!!r);}).join('')}</div>${r?`<p>当前携带数量：${Object.entries(r.supplies).map(([id,n])=>`${itemName(id)} ${n}`).join(' · ')}</p>`:`<label>待放物资<select id="f-kit-item">${Object.entries(KIT).map(([id,k])=>`<option value="${id}" ${kitId===id?'selected':''}>${k.name} · 持有${engine.qty(k.item)}</option>`).join('')}</select></label><div class="button-row">${button('fRotateKit','旋转形状 · '+rotation*90+'°')} ${button('fClearKit','移除选中物资',kitId)}</div><p class="muted">选择物资后点击左上角放置点。选新武器会替换旧武器；旋转只改变待放形状。</p>`}<div class="kit-list">${f.kit.map(e=>`<span>${KIT[e.id].name}${!r?button('fClearKit','移除',e.id):''}</span>`).join('')}</div>${r?Object.entries(r.cargo).map(([id,n])=>`<p>${itemName(id)} ×${n} ${button('fDropCargo','舍弃',id)}</p>`).join(''):''}`)}${card(r?'进行中的远征':'出发与挑战',r?`<p><b>第${r.stage+1}/3站 · ${r.region==='rest'?'林间休息点':REGIONS[r.region].name}</b><br>${r.secured?'已取得路标箱，可以选路':'在入口东侧搜索远征路标箱'}<br>经过 ${Math.round(r.elapsed)} 秒 ${r.mods.includes('timed')?'· 剩余 '+Math.max(0,Math.ceil(180-r.elapsed))+' 秒':''}<br>${r.failed?'挑战超时，仍可以带回战利品':r.mods.map(id=>names[id]).join(' · ')||'普通远征'}</p><div class="button-row">${engine.routeOptions().map(o=>button('fNextRoute',o.name,o.id,'class="primary"')).join('')}${r.stage===2&&r.secured?button('fFinishRoute','完成远征并回家','','class="primary"'):''}${button('fRetreatRoute','撤退回家')}</div>`:`<p>连续探索三站。每站取得路标箱后选择下个地点，第二段可以选择休息；第三站完成后带物资回家。</p><div class="challenge-list">${['noGuns','timed','oneHeal'].map(id=>button('fChallenge',`${f.challenges.includes(id)?'已选 · ':''}${names[id]}`,id,`class="${f.challenges.includes(id)?'active':''}" aria-pressed="${f.challenges.includes(id)}"`)).join('')}</div><div class="button-row">${button('fStartRoute','从住宅区出发','residential','class="primary"',disabledFarm)}${button('fStartRoute','从医院出发','hospital','',disabledFarm)}</div><p>徽章只首次解锁。普通远征100基础分，每项挑战加75分，战利品最多加50分；没有重复刷钱奖励。</p>`)}${card('感染巢与收复',`<p>感染巢位于废墟外围，需要实际攻击摧毁。收复后敌人数量约减少三分之一，奖励3零件和3豆种入库。巢不会重生。</p>${['residential','hospital','warehouse'].map(id=>`<p><b>${REGIONS[id].name}</b> · ${f.territory[id]?'已经收复':'感染巢未清除'}</p>`).join('')}`)}${card('积分与徽章',`<p>${f.badges.length?f.badges.map(id=>names[id]||id).join(' · '):'尚未获得徽章'}</p>${f.records.length?f.records.map(x=>`<p>第${x.day}天 · ${x.success?x.score+'分':'撤退 / 未达成'} · ${x.mods.map(id=>names[id]).join('、')||'普通远征'}</p>`).join(''):'<p class="muted">完成第一趟远征后在这里留下记录。</p>'}`)}</div>`;
 }else if(tab==='combat'){
  const weapon=state.weapon||'pistol',w=engine.weaponStats(weapon),mods=f.weaponMods[weapon]||{};
  body=note('V 切换蹲行 · G 向光标投石 · T 切换精英部位。手机可使用下方按钮；投石朝角色面向方向，消耗随身1石头。')+`<div class="frontier-grid">${card('潜行与誘敌',`<p>蹲行速度降低48%；在废墟草丛里发现范围从230降到80。敌人的警戒条满后才会追击。躲回草丛、远离视线可以摆脱追踪。</p><div class="button-row">${button('fCrouch',f.crouch?'站起':'蹲行')}${button('fStone','返回世界并投石')}</div><p>当前 ${f.crouch?'正在蹲行':'站立'} · ${engine.inCover()?'处于草丛':'未在草丛'}</p>`)}${card('武器改装',`<label>武器<select id="f-weapon">${['pistol','shotgun','rifle'].map(id=>`<option value="${id}" ${weapon===id?'selected':''}>${ITEMS[id].name}</option>`).join('')}</select></label><p>伤害 ${Math.round(w.damage)} · 射程 ${Math.round(w.range)}<br>弹匣 ${w.mag} · 冷却 ${w.cooldown.toFixed(2)}秒 · 噪声 ${Math.round(w.noise)}</p>${['barrel','accessory'].map(slot=>`<label>${slot==='barrel'?'枪管槽':'附件槽'}<select data-f-module-slot="${slot}" data-weapon="${weapon}"><option value="">标准组件</option>${Object.entries(MODULES).filter(([,d])=>d.slot===slot).map(([id,d])=>`<option value="${id}" ${mods[slot]===id?'selected':''}>${d.name} · 持有${engine.qty(id)}</option>`).join('')}</select></label>`).join('')}<p>改装可拆换。同一件附件不能同时装在两把枪上；拆下扩容弹匣会退回多余子弹。</p>`)}${card('制造组件',Object.entries(MODULES).map(([id,d])=>`<div class="module-row"><b>${d.name}</b><p>${d.desc}</p>${costs(d.cost)}${button('fCraftModule','制作',id,'',disabledFarm||!engine.afford(d.cost))}</div>`).join(''))}${card('仓库精英部位',`<p>腿部破坏：速度降低58%。<br>装甲破坏：核心受到135%伤害；装甲完整时核心仅受45%。<br>背包破坏：额外掉落改为废铁；保持完整可取得消音附件。</p><div class="button-row">${['armor','legs','pack','core'].map(id=>button('fAim',({armor:'装甲',legs:'腿部',pack:'背包',core:'核心'}[id]),id,`class="${f.aimPart===id?'primary':''}"`)).join('')}</div><p>选择后，实际命中精英的子弹会伤害对应部位。地形遮挡和武器射程仍生效。</p>`)}</div>`;
 }else if(tab==='investigation'){
  const p=engine.puzzle(),sample=state.sampleId??f.samples.find(i=>!f.identified.includes(i))??0,herb=HERBS[sample];
  body=note('靠近各废墟的供电控制盒按 E，可以操作电路。日志与草药样本要走近拾取；图鉴和日志随时可读。')+`<div class="frontier-grid">${card('线路控制盒',p?`<p>${REGIONS[s.region].name} · ${engine.nearPuzzle()?'位于控制盒旁':'需要靠近控制盒'}<br>线路从左侧输入，沿中间一行送到右侧输出。每格点击旋转90°。</p><div class="circuit-grid">${p.rotation.map((r,i)=>button('fCircuit',r%2===0?'━':'┃',i,`class="${p.power?'powered':''}" aria-label="线路${i+1}，${r%2===0?'横向':'纵向'}"`,!engine.nearPuzzle()||!!p.power)).join('')}</div><p>压力开关 ${p.plate?'已压住':'需要2木材制作配重'} · ${engine.circuitConnected()?'电路接通':'电路未接通'}<br>${p.power?'当前用途：'+(p.power==='door'?'补给门':'安全照明'):'供电用途尚未选择'}</p><div class="button-row">${button('fPressure','压住开关 · 木材2','','',!engine.nearPuzzle()||p.plate)}${button('fPower','供电开门','door','',!engine.nearPuzzle()||!engine.circuitConnected()||!!p.power)}${button('fPower','点亮照明','lights','',!engine.nearPuzzle()||!engine.circuitConnected()||!!p.power)}</div><p>开门获得6零件与12弹药；照明让该地区敌人发现范围降低15%。只能选一种用途。</p>`:'<p>目前不在废墟。住宅、医院、仓库各有一套独立电路。</p>')}${card('转运日志与种子库',`${f.clues.length?f.journalOrder.map((id,i)=>`<div class="clue-row"><strong>${i+1}. ${CLUES[id].title}</strong><p>${CLUES[id].text}</p>${button('fMoveClue','调整阅读顺序',id)}</div>`).join(''):'<p>尚未拾取日志。每个废墟控制盒旁有一张手记。</p>'}<p>已收集 ${f.clues.length}/3 · ${f.vault?'已经定位农场旧窖':'排列日期并输入密码'}</p><label>三位密码<input id="f-vault-code" inputmode="numeric" maxlength="3" placeholder="从日志推理" aria-label="种子库三位密码"></label>${button('fDecode','解码种子库','','class="primary"',f.clues.length<3||f.vault)}`)}${card('未知样本鉴定',f.samples.length?`<label>样本<select id="f-sample">${f.samples.map(i=>`<option value="${i}" ${i===sample?'selected':''}>样本${i+1}${f.identified.includes(i)?' · 已知 '+HERBS[i].name:''}</option>`).join('')}</select></label><p>叶形：${herb.leaf}<br>花色：${herb.flower}<br>气味：${herb.scent}</p><label>鉴定结论<select id="f-herb-name">${HERBS.map(h=>`<option value="${h.id}">${h.name}</option>`).join('')}</select></label>${button('fIdentify','确认鉴定',sample,'class="primary"',f.identified.includes(sample))}<p>${f.identified.includes(sample)?'已鉴定：'+herb.name+' · '+herb.effect:'答错会给提示，不损失样本。'}</p>`:'<p>在废墟控制盒南侧收集未知植物。</p>')}${card('植物图鉴',`<div class="plant-guide">${HERBS.map(h=>`<p><b>${h.name}</b> · ${h.leaf} / ${h.flower} / ${h.scent}<small>${h.effect}</small></p>`).join('')}</div>`)}</div>`;
 }else if(tab==='life'){
  const done=new Set(f.photos.flatMap(p=>p.subjects));
  body=`<div class="frontier-grid">${card(fi(0)+'伙伴犬 · 麦穗',f.dog.rescued?`<p>麦穗会跟随你。废墟中可以让它追踪隐藏物资；前进时距离过远会等待。绿色足迹是它正在追踪的路线。</p><div class="button-row">${button('fTrackDog','追踪气味','','',!['residential','hospital','warehouse'].includes(s.region))}${button('fPetDog','摸摸麦穗 · 每天恢复12耐力','','',f.dog.petDay===s.day)}</div><p>已找出 ${f.dog.found.length}/3 处隐藏物资<br>${f.dog.tracking?'正在追踪：'+REGIONS[f.dog.tracking.region].name:'目前在陪伴你'}</p>`:'<p>住宅区后院有一只饥饿的小犬，带1份面包去救它。靠近后按 E 喂食。</p>')}${card(fi(10)+'相机与构图任务',`<p>H 拍摄游戏画面。先打开相机，再移动寻找构图；照片保留最近6张，可以选一张展示在营地。</p>${[['towerPond','水塔与池塘同框'],['workingResident','工作中的居民'],['rainSign','雨中的留言板'],['frog','生态修复区的青蛙']].map(([id,name])=>`<p>${done.has(id)?'已拍到':'待拍摄'} · ${name}</p>`).join('')}<div class="button-row">${engine.qty('camera')?button('fCamera',f.camera?'关闭取景框':'开启相机并回到世界'):button('fCraftCamera','组装相机 · 零件2 / 废铁4','','',disabledFarm)}${button('fPhoto','返回世界并拍照','','class="primary"',!engine.qty('camera'))}</div>`)}${card('个人相册',f.photos.length?`<div class="photo-grid">${f.photos.map(p=>`<figure><img src="${p.data}" alt="第${p.day}天 ${REGIONS[p.region].name}的游戏照片"><figcaption>第${p.day}天 · ${REGIONS[p.region].name}<small>${p.subjects.map(id=>id==='frog'?'青蛙':names[id]).join(' · ')||'自由摄影'}</small></figcaption>${button('fDisplayPhoto',f.displayPhoto===p.id?'已展示':'展示在营地',p.id,'',f.displayPhoto===p.id)}</figure>`).join('')}</div>`:'<p class="muted">拍下第一张照片后会出现在这里。</p>','wide')}</div>`;
 }else if(tab==='kitchen'){
  const c=f.cooking;
  body=note('料理操作时经营世界暂停，料理计时继续；切换页面或关闭窗口会暂停料理。原来的加工队列仍可正常使用。')+`<div class="frontier-grid">${card('手动料理 · 土豆豆类餐',`<p>准备土豆2、豆类1。料理完成后存入仓库，普通餐恢复体力，操作精准可获得精致餐。</p>${costs({potato:2,bean:1})}${c?`<div id="cooking-live" class="cooking-live"><strong id="cooking-clock">${c.t.toFixed(1)} / 18.0 秒</strong><div class="cooking-track"><span class="cook-window fire"></span><span class="cook-window add"></span><span class="cook-window stir"></span><i id="cooking-marker" style="left:${c.t/18*100}%"></i></div><div class="cooking-actions">${[['fire','开火','3–5秒'],['add','下料','7–9秒'],['stir','搅拌','13–15秒']].map(([id,name,timing])=>button('fCookingAction',`${name}<small>${timing}${c.actions[id]!=null?' · 已操作':''}</small>`,id,`data-cook-action="${id}"`,c.actions[id]!=null)).join('')}</div><p id="cooking-result">已得 ${Math.round(c.score/3*100)} 分 · 达到84分获得精致餐</p></div>`:button('fStartCooking','开始18秒料理','','class="primary"',disabledFarm||!engine.afford({potato:2,bean:1})||['warning','active'].includes(s.horde.phase))}${f.lastMeal?`<p>上次料理：${f.lastMeal.score}分 · ${f.lastMeal.fine?'精致餐':'家常餐'}</p>`:''}`)}${card('可直接吃的手作餐',`${['chefMeal','fineMeal'].map(id=>`<div class="meal-row">${itemIcon(id)}<span><b>${ITEMS[id].name}</b><small>仓库${engine.qty(id,true)-engine.qty(id)} · 随身${engine.qty(id)} · 恢复饥饿${ITEMS[id].food} / 生命${ITEMS[id].heal} / 耐力${ITEMS[id].stamina}</small></span>${button('consume','吃一份',id,'',!engine.qty(id))}</div>`).join('')}<p>从仓库取出后可随身食用，也可带去市场出售。</p>${button('openCraft','打开加工队列')}`)}</div>`;
 }else if(tab==='exhibition'){
  const e=f.exhibition,goods=Object.keys({...s.inventory,...s.storage}).filter(id=>CROPS[id.replace(/^(fine_|hardy_)/,'')]&&engine.qty(id,true)>0);
  body=note('每七天一场收获展。提交的作物实际交给展会，评奖前可以撤回。品质、不同品种和本周主题共同评分，85分获奖。')+`<div class="frontier-grid">${card(fi(11)+'第'+(e.week+1)+'周收获展',`<p>评奖日：第${e.due}天 · 当前第${s.day}天<br>主题：<b>${CROPS[engine.exhibitionTheme()].name}</b> · 基础8分/份 · 优质+22/份 · 每种不同作物+12 · 符合主题+25</p><div class="exhibit-slots">${[0,1,2].map(i=>`<div>${e.entries[i]?`${itemIcon(e.entries[i])}<b>${itemName(e.entries[i])}</b>${button('fRemoveExhibit','撤回到仓库',i,'',e.judged)}`:'<b>待提交</b><small>每格1份作物</small>'}</div>`).join('')}</div><p>预计得分 <strong>${engine.exhibitionScore()}</strong>${e.result?' · '+(e.result.win?'获奖':'参与完成'):''}</p><label>选择收成<select id="f-exhibit-item">${goods.length?goods.map(id=>`<option value="${id}">${itemName(id)} · 持有${engine.qty(id,true)}</option>`).join(''):'<option value="">没有可提交的作物</option>'}</select></label><div class="button-row">${button('fEnterExhibit','提交1份','','',disabledFarm||e.judged||e.entries.length>=3||!goods.length)}${button('fJudgeExhibit','评选收获展','','class="primary"',e.judged||s.day<e.due||!e.entries.length)}</div><p>获奖得到奖杯、80金币与1蓝图凭证；未获奖得到4萝卜种子。每周只评一次。</p>`)}${card('营地展示',`<p>已获得 ${f.trophies} 座奖杯。获奖后可在建筑菜单摆放奖杯。</p>${button('build','摆放收获展奖杯','harvestTrophy','',disabledFarm||!f.trophies)}<p>展会之外，继续接订单、加工和经营摊位。下一周会更换主题作物。</p>`)}</div>`;
 }
 return `<div class="frontier-page">${h.compact?'':tabs}<div class="frontier-body">${body}</div></div>`;
}
